    float4 newLayer( float4 a, float4 b) { return a * (1. - b.a) + b; }
    float2x2 rot2m(float a){ float s = sin(a); float c = cos(a); return float2x2(c, -s, s, c); }
    float2 l2s( float2 v ) { return (float4(v,0.,1.)*amzLayerToScreen()).xy; }
        float Random(float x)
        {
         return fract(sin(x * 123.456) * 23.4567 + sin(x * 345.678) * 45.6789 + sin(x * 456.789) * 56.789);
        }
        float3 GetParticleColour( float3 vParticlePos, float fParticleSize, float3 vRayDir )
        {
         float2 vNormDir = normalize(vRayDir.xy);
         float d1 = dot(vParticlePos.xy, vNormDir.xy) / length(vRayDir.xy);
         float3 vClosest2d = vRayDir * d1;
         float3 vClampedPos = vParticlePos;
         vClampedPos.z = clamp(vClosest2d.z, vParticlePos.z - (fLength/60.0), vParticlePos.z + (fLength/60.0));
         float d = dot(vClampedPos, vRayDir);
         float3 vClosestPos = vRayDir * d;
         float3 vDeltaPos = vClampedPos - vClosestPos;
         float fClosestDist = length(vDeltaPos) / fParticleSize;
         float fShade = clamp(1.0 - fClosestDist, 0.0, 1.0);
         fShade = fShade * exp2(-d * fDepthFade) * fBrightness;
         return float3(fShade);
        }
        float3 GetParticlePos( float3 vRayDir, float fZPos, float fSeed )
        {
         float fAngle = atan(vRayDir.x, vRayDir.y);
         float fAngleFraction = fract(fAngle / (3.14 * 2.0));
         float fSegment = floor(fAngleFraction * 121.0 + fSeed) + 0.5 - fSeed;
         float fParticleAngle = fSegment / 121.0 * (3.14 * 2.0);
         float fSegmentPos = fSegment / 121.0;
         float fRadius = fMinDist + Random(fSegmentPos + fSeed) * (fMaxDist - fMinDist);
         float tunnelZ = vRayDir.z / length(vRayDir.xy / fRadius);
         tunnelZ += fZPos;
         float fRepeat = fRepeatMin + Random(fSegmentPos + 0.1 + fSeed) * (fRepeatMax - fRepeatMin);
         float fParticleZ = (ceil(tunnelZ / fRepeat) - 0.5) * fRepeat - fZPos;
         return float3( sin(fParticleAngle) * fRadius, cos(fParticleAngle) * fRadius, fParticleZ );
        }
        float3 Starfield( float3 vRayDir, float fZPos, float fSeed )
        {
         float3 vParticlePos = GetParticlePos(vRayDir, fZPos, fSeed);
         return GetParticleColour(vParticlePos, fParticleSize, vRayDir);
        }
        float3 RotateX( float3 vPos, float fAngle )
        {
            float s = sin(fAngle);
            float c = cos(fAngle);
            float3 vResult = float3( vPos.x, c * vPos.y + s * vPos.z, -s * vPos.y + c * vPos.z);
            return vResult;
        }
        float3 RotateY( float3 vPos, float fAngle )
        {
            float s = sin(fAngle);
            float c = cos(fAngle);
            float3 vResult = float3( c * vPos.x + s * vPos.z, vPos.y, -s * vPos.x + c * vPos.z);
            return vResult;
        }
        float3 RotateZ( float3 vPos, float fAngle )
        {
            float s = sin(fAngle);
            float c = cos(fAngle);
            float3 vResult = float3( c * vPos.x + s * vPos.y, -s * vPos.x + c * vPos.y, vPos.z);
            return vResult;
        }
        void amzRender() {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float ovA = (overdrawOn>0.5) ? 1.0 : texColor.a;
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * ovA;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float2 iMouse = float2(0.5, 0.5);
        float iTime = (autop>0.5)? PROGRESS + (time*SPEED) : PROGRESS;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= scale;
        satriyaid *= rot2m((0.0+angle)*0.0174533);
        satriyaid += float2((0.0+position.x), (0.0+position.y))*float2(-1.,1.)/500.;
        float2 scaleVec;
        scaleVec = float2(scale*stretch.x,scale*stretch.y);
        satriyaid /= scaleVec;
     float4 fragColor;
         float2 vScreenPos = satriyaid;
         float3 vRayDir = normalize(float3(vScreenPos, 1.0));
         float3 vEuler = amzp_ROT *0.01;
         if((SPLITXYZ>0.5)) { vEuler = float3(ROT2, ROT3, ROT4); }
         vRayDir = RotateX(vRayDir, vEuler.y);
         vRayDir = RotateY(vRayDir, vEuler.x);
         vRayDir = RotateZ(vRayDir, vEuler.z);
         float fShade = 0.0;
         float a = 0.2;
         float b = 10.0;
         float c = 1.0;
         float fZPos = 5.0 + iTime * c + sin(iTime * a) * b;
         float fSeed = FSEED;
         float3 vResult = mix(float3(0.0, 0.0, 0.0), float3(0.0, 0.0, 0.0), vRayDir.y * 0.5 + 0.5);
         for(int i=0; i<int(AMOUNT); i++)
         {
          vResult += Starfield(vRayDir, fZPos, fSeed);
          fSeed += 1.234;
         }
         fragColor = float4(sqrt(vResult),1.0);
         float4 factor;
         const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float luminance = dot(fragColor.rgb, luminanceWeighting);
            float4 gradmap = mix(color1,color2,luminance)*fragColor.a;
         factor = mix(texColorX,gradmap,1.0);
        float4 resultfinal;
          if( int(blendMode)==0 ) { resultfinal = (factor * hardness) * ovA; }
          else if( int(blendMode)==1 ) { factor *= hardness;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/max(texColor.a,0.0001))*c.rgb,1.0) * ovA; }
          else if( int(blendMode)==2 ) { factor *= hardness;
            resultfinal = float4( 1.-((1.-(texColor.rgb/max(texColor.a,0.0001)))*(1.-factor.rgb)),1.0) * ovA; }
          else if( int(blendMode)==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * ovA; }
     amzOutput = mix(texColor, resultfinal, alpha);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
